(() => {
  const pick = (sel) => document.querySelector(sel)?.innerText?.trim() || '';
  const title = document.title;
  const h1 = pick('h1');
  const article = pick('article') || pick('main') || pick('.content') || pick('#content');
  const body = document.body.innerText.replace(/\n{3,}/g, '\n\n').trim();
  return JSON.stringify({ url: location.href, title, h1, article: article.slice(0, 4000), bodyLength: body.length, body: body.slice(0, 6000) });
})()

